        private static void doEcoute(Object data) {
            // thread for listening to customer requests
            try {
                // create the service
                service = new TcpListener(IPAddress.Any, port);
                // launch it
                service.Start();
                // the server is active
                actif = true;
                // follow-up
                Console.WriteLine("Serveur de calcul d'impôt lancé sur le port {0}", port);
                // customer service loop
                TcpClient tcpClient = null;
                // customer no
                int numClient = 0;
                // endless loop
                while (true) {
                    // waiting for a customer
                    tcpClient = service.AcceptTcpClient();
                    // the service is provided by another task
                    ThreadPool.QueueUserWorkItem(doService, new Client() { CanalTcp = tcpClient, NumClient = numClient });
                    // next customer
                    numClient++;
                }
            } catch (Exception ex) {
                // we report the error
                Console.WriteLine("L'erreur suivante s'est produite sur le serveur : {0}", ex.Message);
            }
        }

        // customer info
        internal class Client {
                        public TcpClient CanalTcp { get; set        ; }     // customer liaison
                        public int NumClient { get; set            ; }          // customer no
}
</code></pre> <p>This code is similar to that of the echo server studied in paragraph 11.6.1. We only comment on what is different:</p> <ul> <li>line 7: listening service launched   </li> <li>line 9: notes that the service is now active   </li> </ul> <p>Line 21, customers are served by service threads running the doService next :</p> <pre><code>
private static void doService(Object infos) {
            // the customer is picked up and served
            Client client = infos as Client;
            // renders service to the customer
            Console.WriteLine("Début du service au client {0}", client.NumClient);
            // operation link TcpClient
            try {
                using (TcpClient tcpClient = client.CanalTcp) {
                    using (NetworkStream networkStream = tcpClient.GetStream()) {
                        using (StreamReader reader = new StreamReader(networkStream)) {
                            using (StreamWriter writer = new StreamWriter(networkStream)) {
                                // unbuffered output stream
                                writer.AutoFlush = true;
                                // send a welcome message to the customer
                                writer.WriteLine("Bienvenue sur le serveur de calcul de l'impôt");
                                // loop read request/write response
                                string demande = null;
                                bool serviceFini = false;
                                while (!serviceFini &amp;&amp; (demande = reader.ReadLine()) != null) {
                                    // console monitoring
                                    if (echo) {
                                        Console.WriteLine("&lt;--- Client {0} : {1}", client.NumClient, demande);
                                    }
                                    // demand analysis
                                    demande = demande.Trim().ToLower();
                                    // empty request?
                                    if (demande.Length == 0) {
                                        // erroneous request
                                        writeClient(writer,client.NumClient,"Commande non reconnue. Utilisez la commande aide.");
                                        return;
                                    }

                                    // demand is broken down into fields
                                    string[] champs = Regex.Split(demande, @"\s+");
                                    // analysis
                                    switch (champs[0].ToLower()) {
                                        case "aide":
                                            writeClient(writer, client.NumClient, "Commandes acceptées\n1-aide\n2-impot marié(O/N) nbEnfants salaireAnnuel\n3-aurevoir");
                                            break;
                                        case "impot":
                                            // tax calculation
                                            writeClient(writer, client.NumClient, calculImpot(writer, client.NumClient, champs));
                                            break;
                                        case "aurevoir":
                                            serviceFini = true;
                                            writeClient(writer, client.NumClient, "Au revoir...");
                                            break;
                                        default:
                                            writeClient(writer, client.NumClient, "Commande non reconnue. Utilisez la commande aide.");
                                            break;
                                    }
                                }
                            }
                        }
                    }
                }
            } catch (Exception e) {
                // error
                Console.WriteLine("L'erreur suivante s'est produite lors du service au client {0} : {1}", client.NumClient, e.Message);
            } finally {
                Console.WriteLine("Fin du service au client {0}", client.NumClient);
            }
        }

        private static void writeClient(StreamWriter writer, int numClient, string message) {
            // echo console ?
            if (echo) {
                Console.WriteLine("---&gt; Client {0} : {1}", numClient, message);
            }
            // send msg to customer
            writer.WriteLine(message);
}
</code></pre> <p>Once again, the code is similar to that of the echo server studied in paragraph 11.6.1 We only comment on what is different:</p> <ul> <li>line 15: once the client is connected, the server sends a welcome message.   </li> <li>lines 19-52: the loop for reading customer commands. The loop stops when the customer sends the "goodbye".   </li> <li>line 27: case of an empty order   </li> <li>line 34: the request is broken down into fields for analysis   </li> <li>line 37: order help : the customer requests a list of authorized orders   </li> <li>line 40: order tax : the client requests a tax calculation. We respond with the message returned by the calculImpot which we'll be detailing shortly.   </li> <li>line 44: order goodbye : the customer indicates that he is finished.   </li> <li>line 45: we're getting ready to leave the reading loop of customer requests (lines 19-52)   </li> <li>line 46: we reply to the customer with a good-bye message   </li> <li>line 48: an incorrect order. An error message is sent to the customer.   </li> </ul> <p>Order processing tax is ensured by the calculImpot next :</p> <pre><code>
private static string calculImpot(StreamWriter writer, int numClient, string[] champs) {
            // request calculation married(Y/N) nbEnfants salaireAnnuel
            // 4 fields are required
            if (champs.Length != 4) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // fields [1]
            string marié = champs[1];
            if (marié != "o" &amp;&amp; marié != "n") {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // fields [2]
            int nbEnfants;
            if (!int.TryParse(champs[2], out nbEnfants)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // fields [3]
            int salaireAnnuel;
            if (!int.TryParse(champs[3], out salaireAnnuel)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // that's it - tax calculation
            int impot = 0;
            try {
                impot = metier.CalculerImpot(marié == "o", nbEnfants, salaireAnnuel);
                return impot.ToString();
            } catch (Exception ex) {
                return ex.Message;
            }
        }
</code></pre> <ul> <li>line 1: the method receives the array of command fields as the 3rd parameter tax. If correctly formulated, it is of the form married tax nbEnfants salaireAnnuel. The result of the method is the response to be sent to the client.   </li> <li>line 4: check that the command has 4 fields   </li> <li>line 8: check that the married is valid   </li> <li>line 14: check that the nbEnfants is valid   </li> <li>line 19: check that the salaireAnnuel is valid   </li> <li>line 25: tax is calculated using the CalculerImpot of the [metier] layer. Remember that this layer is encapsulated in a DLL.   </li> <li>line 26: if the [metier] layer has returned a result, it is returned to the customer.   </li> <li>line 28: if the [metier] layer has thrown an exception, the exception message is returned to the client.   </li> </ul> <p></p>
